import java.util.*;
import java.io.*;

public class Main {
    static class Edge {
        int to, cap, cost, rev;
        public Edge(int to, int cap, int cost, int rev) {
            this.to = to;
            this.cap = cap;
            this.cost = cost;
            this.rev = rev;
        }
    }

    static class MinCostFlow {
        static final int MAX_V = 5010;
        int V;
        List<Edge>[] G = new ArrayList[MAX_V];
        int[] h = new int[MAX_V];
        int[] dist = new int[MAX_V];
        int[] prevv = new int[MAX_V];
        int[] preve = new int[MAX_V];

        public MinCostFlow() {
            for (int i = 0; i < MAX_V; i++) {
                G[i] = new ArrayList<>();
            }
        }

        void init(int n) {
            V = n;
            for (int i = 0; i < V; i++) {
                G[i].clear();
            }
        }

        void addEdge(int from, int to, int cap, int cost) {
            G[from].add(new Edge(to, cap, cost, G[to].size()));
            G[to].add(new Edge(from, 0, -cost, G[from].size() - 1));
        }

        int minCostFlow(int s, int t, int f) {
            int res = 0;
            Arrays.fill(h, 0);
            while (f > 0) {
                PriorityQueue<int[]> que = new PriorityQueue<>(Comparator.comparingInt(a -> a[0]));
                Arrays.fill(dist, Integer.MAX_VALUE);
                dist[s] = 0;
                que.offer(new int[]{0, s});
                while (!que.isEmpty()) {
                    int[] p = que.poll();
                    int v = p[1];
                    if (dist[v] < p[0]) continue;
                    for (int i = 0; i < G[v].size(); i++) {
                        Edge e = G[v].get(i);
                        if (e.cap > 0 && dist[e.to] > dist[v] + e.cost + h[v] - h[e.to]) {
                            dist[e.to] = dist[v] + e.cost + h[v] - h[e.to];
                            prevv[e.to] = v;
                            preve[e.to] = i;
                            que.offer(new int[]{dist[e.to], e.to});
                        }
                    }
                }
                if (dist[t] == Integer.MAX_VALUE) {
                    return -1;
                }
                for (int v = 0; v < V; v++) h[v] += dist[v];
                int d = f;
                for (int v = t; v != s; v = prevv[v]) {
                    d = Math.min(d, G[prevv[v]].get(preve[v]).cap);
                }
                f -= d;
                res += d * h[t];
                for (int v = t; v != s; v = prevv[v]) {
                    Edge e = G[prevv[v]].get(preve[v]);
                    e.cap -= d;
                    G[v].get(e.rev).cap += d;
                }
            }
            return res;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        int k = sc.nextInt();
        int c = sc.nextInt();
        int d = sc.nextInt();

        int[] a = new int[50];
        int[] cnt = new int[50];
        for (int i = 0; i < k; i++) {
            a[i] = sc.nextInt();
            cnt[a[i] - 1]++;
        }

        List<Integer>[] e = new ArrayList[50];
        for (int i = 0; i < 50; i++) {
            e[i] = new ArrayList<>();
        }

        for (int i = 0; i < m; i++) {
            int x = sc.nextInt() - 1;
            int y = sc.nextInt() - 1;
            e[x].add(y);
            e[y].add(x);
        }

        int T = 100;
        MinCostFlow mcf = new MinCostFlow();
        mcf.init(n * T + 2);
        int source = n * T;
        int sink = n * T + 1;

        for (int i = 0; i < n; i++) {
            mcf.addEdge(source, i, cnt[i], 0);
        }

        for (int i = 0; i < T; i++) {
            mcf.addEdge(i * n, sink, k, c * i);
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < T - 1; j++) {
                mcf.addEdge(j * n + i, (j + 1) * n + i, k, 0);
            }
            for (int to : e[i]) {
                for (int j = 0; j < T - 1; j++) {
                    for (int u = 0; u < k; u++) {
                        int cost = (u + 1) * (u + 1) * d - u * u * d;
                        mcf.addEdge(j * n + i, (j + 1) * n + to, 1, cost);
                    }
                }
            }
        }

        System.out.println(mcf.minCostFlow(source, sink, k));
        sc.close();
    }
}

